sys_variable_value.value:
(function execute(inputs, outputs) {
  var TABLE_BASE = 'x_1834930_office_0_office_base';
  var TABLE_REG  = 'x_1834930_office_0_base_registration';

  outputs.subject = '';
  outputs.body_text = '';
  outputs.approved_count = 0;
  outputs.capacity = 0;
  outputs.manager_email = '';
  outputs.manager_name = '';
  outputs.base_sys_id = '';

  try {
    
    var baseId = '';
    var ref = inputs.base;
    if (ref) {
      if (typeof ref === 'string') {
        baseId = String(ref);
      } else if (typeof ref === 'object') {
        baseId = String(ref.sys_id || ref.value || ref.display_value || '');
      }
    }
    if (!baseId) {
      outputs.error = 'Missing base sys_id.';
      return;
    }

    var base = new GlideRecord(TABLE_BASE);
    if (!base.get(baseId)) {
      outputs.error = 'Office Base not found.';
      return;
    }

    outputs.base_sys_id   = base.getUniqueValue();
    outputs.capacity      = parseInt(base.getValue('max_capacity'), 10) || 0;
    outputs.manager_name  = base.getDisplayValue('manager') || '';
    outputs.manager_email = (base.manager && base.manager.email) ? String(base.manager.email) : '';

    var baseName = base.getValue('name') || '';
    var loc = base.getValue('city') || '';
    if (base.getValue('state')) loc += (loc ? ', ' : '') + base.getValue('state');

    var roster = [];
    var gr = new GlideRecord(TABLE_REG);
    gr.addQuery('base', baseId);
    gr.addQuery('state', '2');
    gr.orderBy('user');
    gr.query();

    var i = 1;
    while (gr.next()) {
      var user = gr.getDisplayValue('user') || '';
      var func = gr.getDisplayValue('function') || '';
      roster.push(i + '. ' + user + (func ? ' — ' + func : ''));
      i++;
      outputs.approved_count++;
    }
    if (outputs.approved_count === 0) {
      roster.push('(No approved registrations)');
    }

    var nowGdt = new GlideDateTime();
    var nowStr = nowGdt.getDisplayValue();

    var lines = [];
    lines.push('Hello ' + (outputs.manager_name || 'Base Manager') + ',');
    lines.push('');
    lines.push('The office base "' + baseName + '" has reached its maximum capacity (' + outputs.capacity + ') and all registrations are approved as of ' + nowStr + '.');
    lines.push('');
    lines.push('Base details:');
    lines.push('- Name: ' + baseName);
    lines.push('- Location: ' + loc);
    lines.push('- Capacity: ' + outputs.capacity);
    lines.push('- Manager: ' + (outputs.manager_name || ''));
    lines.push('');
    lines.push('Approved roster (' + outputs.approved_count + '/' + outputs.capacity + '):');
    Array.prototype.push.apply(lines, roster);
    lines.push('');
    lines.push('If you need to make changes, you can manage registrations directly in the Office Manager application.');
    lines.push('');
    lines.push('Regards,');
    lines.push('Office Manager');

    outputs.body_text = lines.join('\n');
    outputs.subject = 'Office Base ' + baseName + ' is full (' + outputs.capacity + ') – Approved roster';

  } catch (e) {
    outputs.error = (e && e.message) ? e.message : String(e);
  }
})(inputs, outputs);

